args.sparql:
SELECT DISTINCT ?performer ?performerLabel ?award ?awardLabel WHERE {
  dbr:Little_More_(Royalty) dbo:artist ?performer .
  OPTIONAL { ?performer dbo:award ?award . }
  OPTIONAL { ?performer dbp:awards ?award . }
  OPTIONAL { ?performer dbp:award ?award . }
  OPTIONAL { ?performer rdfs:label ?performerLabel . FILTER(lang(?performerLabel) = "en") }
  OPTIONAL { ?award rdfs:label ?awardLabel . FILTER(lang(?awardLabel) = "en") }
} LIMIT 50

